<script setup lang="ts">
import {onMounted,onUnmounted,ref,computed} from 'vue'
import {useAuth} from '../../entities/auth/model'
import {request,errorMessage,isCancelled} from '../../shared/api/client'
import type {Operations} from '../../shared/interfaces'
import {text,datetime,providerCost} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Empty from '../../shared/ui/Empty.vue'
import Notice from '../../shared/ui/Notice.vue'
const auth=useAuth(),data=ref<Operations|null>(null),loading=ref(true),error=ref(''),success=ref(''),tab=ref('jobs'),purgeOpen=ref(false),busy=ref(false)
let timer:ReturnType<typeof setInterval>|undefined
const rows=computed(()=>data.value?(tab.value==='audit'?data.value.audit:tab.value==='sync'?data.value.sync_runs:tab.value==='deliveries'?data.value.deliveries:data.value.jobs):[])
const pending=computed(()=>data.value?.jobs.filter(j=>['pending','queued','running','retry'].includes(String(j.state))).length||0),failed=computed(()=>data.value?.jobs.filter(j=>['failed','error','dead'].includes(String(j.state))).length||0)
function state(value:unknown){return({pending:'В очереди',queued:'В очереди',running:'В работе',retry:'Повтор ожидается',completed:'Готово',done:'Готово',delivered:'Доставлено',failed:'Ошибка',error:'Ошибка',dead:'Требует проверки',skipped:'Пропущено',uncertain:'Нужна проверка'} as Record<string,string>)[String(value)]||text(value)}
async function load(background=false){if(!background)loading.value=true;try{data.value=await request<Operations>('/operations');error.value=''}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
async function retry(id:unknown){busy.value=true;try{await request('/operations/jobs/'+String(id)+'/retry',{method:'POST',body:{}});success.value='Задание возвращено в очередь';await load(true)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function purge(){busy.value=true;try{await request('/operations/purge',{method:'POST',body:{}});success.value='Удаление данных по срокам хранения поставлено в очередь';purgeOpen.value=false;await load(true)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load(true)},10000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">Прозрачный путь от звонка до результата</span><h1>Обработка и аудит</h1><p>Очереди, ошибки провайдеров, расход и история изменений компании.</p></div><div class="heading-actions"><button class="button" @click="load()"><Icon name="refresh" :size="15"/>Обновить</button><button v-if="auth.isOwner" class="button" @click="purgeOpen=true">Применить сроки хранения</button></div></div><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><Empty v-if="loading&&!data" loading/><template v-else-if="data"><div class="cards-stat-small"><div class="card mini-stat"><strong>{{pending}}</strong><span>Заданий в обработке</span></div><div class="card mini-stat"><strong style="color:#bc7d61">{{failed}}</strong><span>Требуют внимания</span></div><div class="card mini-stat"><strong>{{providerCost(data.usage.cost??data.usage.total_cost)}}</strong><span>Расход провайдеров за период</span></div></div><div v-if="Object.keys(data.health).length" class="card" style="margin-bottom:22px"><div class="card-body"><h4>Состояние компонентов</h4><div class="inline-labels"><span v-for="(value,key) in data.health" :key="key" class="badge" :class="value===true||['ok','ready','healthy','connected'].includes(String(value))?'teal':'amber'">{{key}}: {{text(value)}}</span></div></div></div><div class="card"><div class="tabs"><button :class="{active:tab==='jobs'}" @click="tab='jobs'">Задания <span class="tab-count">{{data.jobs.length}}</span></button><button :class="{active:tab==='sync'}" @click="tab='sync'">Импорт истории</button><button :class="{active:tab==='deliveries'}" @click="tab='deliveries'">Доставка результатов</button><button :class="{active:tab==='audit'}" @click="tab='audit'">Аудит изменений</button></div><div v-if="rows.length" class="table-wrap"><table class="data-table"><thead><tr><th>{{tab==='audit'?'Действие':'Операция'}}</th><th>{{tab==='audit'?'Участник':'Состояние'}}</th><th>Создано</th><th>{{tab==='audit'?'Объект':'Попытки / следующая'}}</th><th>Подробности</th><th></th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="String(row.id||i)"><td class="primary-text">{{text(row.kind||row.action||row.event_type||row.provider)}}</td><td><span v-if="tab!=='audit'" class="job-state" :class="String(row.state)">{{state(row.state)}}</span><span v-else>{{text(row.actor||row.user_id)}}</span></td><td>{{datetime(row.created_at||row.started_at)}}</td><td v-if="tab==='audit'">{{text(row.subject_id||row.entity_id)}}</td><td v-else>{{text(row.attempts??0)}}<small v-if="row.next_attempt_at">{{datetime(row.next_attempt_at)}}</small></td><td style="max-width:320px;white-space:normal;font-size:10px">{{text(row.last_error||row.error||row.message||row.details)}}</td><td><button v-if="tab==='jobs'&&auth.isOwner&&['failed','error','dead','retry','uncertain'].includes(String(row.state))" class="button small" :disabled="busy" @click="retry(row.id)">Повторить</button></td></tr></tbody></table></div><Empty v-else title="В этом разделе пока нет записей" description="Здесь появятся операции импорта, обработки разговоров и изменения данных."/></div><div v-if="Object.keys(data.usage).length" class="card" style="margin-top:22px"><div class="card-header"><h3>Использование провайдеров</h3></div><div class="card-body"><dl class="info-grid"><div v-for="(value,key) in data.usage" :key="key"><dt>{{key}}</dt><dd>{{text(value)}}</dd></div></dl></div></div></template><div v-if="purgeOpen" class="modal-shade" @click.self="purgeOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-label="Очистка по срокам хранения"><div class="modal-body"><h2>Применить сроки хранения?</h2><p class="muted">Просроченные записи, тексты и производные результаты будут удалены по правилам текущей компании. Настройки других компаний не изменятся.</p><div class="form-actions"><button class="button" @click="purgeOpen=false">Отмена</button><button class="button danger" :disabled="busy" @click="purge">Запустить очистку</button></div></div></section></div></template>
